// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNumber) public {
        vm.assume(blockNumber > 0);
        vm.roll(blockNumber);
        vm.warp(1);
        address sender = address(0x1234);
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        (bool ok,) = address(c).call{value: 10 ether}("");
        require(ok, "call failed");
        uint256 bal = address(c).balance;
        bool balanceZero = (bal == 0);
        bool expectedZero = (block.number % 15 == 0);
        assertTrue(balanceZero == expectedZero);
    }
}
